\"\"\"Minimal OpenAI Responses API client using only the Python standard library.

Usage:
    export OPENAI_API_KEY=\"sk-...\"
    python3 openai_client.py \"Write a haiku about the sea\"

Or from Python:
    from openai_client import OpenAIClient
    client = OpenAIClient()
    print(client.ask(\"Hello"'!"))
"""

import argparse
import json
import os
import sys
import urllib.error
import urllib.request

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(Exception):
    """Raised when the API returns an error or an unexpected response."""

    def __init__(self, message, status=None, body=None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    def __init__(self, api_key=None, model=None, base_url=None, timeout=60.0):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError("No API key provided; set OPENAI_API_KEY or pass api_key.")
        self.model = model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL)
        self.base_url = (base_url or os.environ.get("OPENAI_BASE_URL", DEFAULT_BASE_URL)).rstrip("/")
        if not self.base_url.startswith("https://"):
            raise OpenAIError("base_url must use HTTPS to protect your API key and prompts.")
        self.timeout = timeout

    def create_response(self, prompt, instructions=None, model=None, store=False, **params):
        """Send a text prompt and return the full parsed JSON response.

        `store` defaults to False so the response is not stored by OpenAI for
        later retrieval via the API.
        """
        payload = {"model": model or self.model, "input": prompt, "store": store}
        if instructions:
            payload["instructions"] = instructions
        payload.update(params)

        request = urllib.request.Request(
            f"{self.base_url}/responses",
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                body = response.read().decode("utf-8")
        except urllib.error.HTTPError as error:
            body = error.read().decode("utf-8", errors="replace")
            message = body
            try:
                message = json.loads(body)["error"]["message"]
            except (ValueError, KeyError, TypeError):
                pass
            raise OpenAIError(f"HTTP {error.code}: {message}", status=error.code, body=body) from None
        except urllib.error.URLError as error:
            raise OpenAIError(f"Network error: {error.reason}") from None

        try:
            data = json.loads(body)
        except ValueError:
            raise OpenAIError("Invalid JSON in API response.", body=body) from None
        if data.get("error"):
            raise OpenAIError(str(data["error"].get("message", data["error"])), body=body)
        return data

    def ask(self, prompt, instructions=None, **params):
        """Send a text prompt and return the generated text."""
        return extract_text(self.create_response(prompt, instructions=instructions, **params))


def extract_text(response):
    """Concatenate all output_text parts from a Responses API result."""
    if isinstance(response.get("output_text"), str):
        return response["output_text"]
    parts = []
    for item in response.get("output", []):
        if item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Send a private text prompt to the OpenAI Responses API.")
    parser.add_argument("prompt", nargs="?", help="Prompt text (reads stdin if omitted).")
    parser.add_argument("-m", "--model", help=f"Model name (default: $OPENAI_MODEL or {DEFAULT_MODEL}).")
    parser.add_argument("-i", "--instructions", help="Optional system/developer instructions.")
    parser.add_argument("--timeout", type=float, default=60.0, help="Request timeout in seconds.")
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    if not prompt.strip():
        parser.error("prompt is empty")

    try:
        client = OpenAIClient(model=args.model, timeout=args.timeout)
        print(client.ask(prompt, instructions=args.instructions))
    except OpenAIError as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
